     7→class Chalk::GrammarRule {
     8→
     9→    # Supports both exact token matching and lexeme/regex patterns for terminals
    10→    # Use parse() for pre-tokenized input, parse_string() for lexeme matching
    11→    use overload '""' => 'to_string';
    12→
    13→    state $next_id = 0;    # auto-incrementing rule ID
    14→    field $id  :reader = $next_id++;
    15→    field $lhs :param :reader;
    16→    field $rhs :param :reader;
    17→    field $probability :param :reader = 1.0;
    18→    field $nullable;
    19→
    20→    method is_right_recursive() { $lhs eq $rhs->[-1] }
    21→    method is_left_recursive()  { $lhs eq $rhs->[0] }
    22→
    23→    method is_nullable( $grammar, $seen = {} ) {
    24→        return $nullable if defined($nullable);    # memoize nullable
    25→
    26→        # Empty production is nullable
    27→        return $nullable = 1 if $rhs->@* == 0;
    28→
    29→        # All symbols in RHS must be nullable
    30→        return $nullable = 1 if all {
    31→            my @rules = $grammar->rules_for($_);
    32→
    33→            # Terminals (no rules) - check if nullable
    34→            unless (@rules) {
    35→
    36→                # For regex terminals, test if they match empty string
    37→                if ( ref($_) eq 'Regexp' ) {
    38→                    return "" =~ $_;
    39→                }
    40→
    41→    # String terminals are not nullable (empty string would be in grammar as [])
    42→                return 0;
    43→            }
    44→
    45→            # In cycle, assume not nullable
    46→            return 0 if $seen->{$_};
    47→
    48→            # Check if this symbol is nullable via any of its rules
    49→            $seen->{$_} = 1;
    50→            return 0 unless any { $_->is_nullable( $grammar, $seen ) } @rules;
    51→        } $rhs->@*;
    52→
    53→        return $nullable = 0;
    54→    }
    55→
    56→    method to_string(@args) {
    57→        return "($id) $lhs -> " . join( ' ', $rhs->@* );
    58→    }
    59→
    60→    method terminal_to_regex($terminal) {
    61→        state %seen;
    62→
    63→        # Convert terminal to regex pattern
    64→        # If already a regex, return as-is
    65→        # If string literal, escape and convert to regex
    66→        return $seen{$terminal} //=
    67→          ref($terminal) eq 'Regexp' ? $terminal : qr/\Q$terminal\E/;
    68→    }
    69→
    70→    # Default semantic action: return children as array (for AST construction)
    71→    # Subclasses can override this method to provide custom semantic actions
    72→    method evaluate($context) {
    73→        return [ map { $_->extract } $context->children->@* ];
    74→    }
    75→}
